/**
 * Regulatory assurance + board reporting seed (schema v7).
 */
export function applyAssuranceSeed(state) {
  state.assuranceRatingScaleId = 'SCALE-IMPL-001';
  state.assuranceMethodologies = buildMethodologies();
  state.reportingPeriods = buildReportingPeriods();
  state.assuranceReviews = buildAssuranceReviews();
  state.assuranceFindings = buildFindings();
  state.managementAttestations = buildManagementAttestations();
  state.assurancePacks = buildAssurancePacks();
  state.boardPacks = buildBoardPacks();
  state.periodSnapshots = buildPeriodSnapshots();
  state.periodTrendHistory = buildTrendHistory();
  enrichAssuranceEntities(state);
  return state;
}

