function enrichAssuranceEntities(state) {
  const ch1 = state.changes.find((c) => c.id === 'CHG-001');
  if (ch1) {
    ch1.implementationAssuranceRating = 'Fully Implemented';
    ch1.assuranceReviewStatus = 'Complete';
    ch1.primaryAssuranceReviewId = 'AR-CHG-001-COMP';
    ch1.assurancePackId = 'PACK-CHG-001-001';
  }
  const ch10 = state.changes.find((c) => c.id === 'CHG-010');
  if (ch10) {
    ch10.implementationAssuranceRating = 'Partially Implemented';
    ch10.assuranceReviewStatus = 'Complete';
    ch10.primaryAssuranceReviewId = 'AR-CHG-010-COMP';
    ch10.assurancePackId = 'PACK-CHG-010-001';
  }
  const ev9 = state.evidence.find((e) => e.id === 'EVD-009');
  if (ev9) {
    ev9.qualityStatus = 'Sufficient with Observations';
    ev9.linkedAssuranceReviewIds = ['AR-CHG-001-COMP', 'AR-OBL-0142'];
  }
  const finding = state.assuranceFindings.find((f) => f.id === 'FIND-CHG-001-001');
  if (finding) finding.changeId = 'CHG-001';

  if (!state.auditEvents) state.auditEvents = [];
  state.auditEvents.unshift(
    {
      id: 'AUD-ASSURE-001',
      timestamp: '2026-10-05T14:30:00Z',
      user: 'Michael Grant',
      action: 'Assurance opinion issued',
      recordType: 'Assurance Review',
      recordId: 'AR-CHG-001-COMP',
      newValue: 'Substantially Implemented',
      relatedIds: ['CHG-001', 'FIND-CHG-001-001'],
    },
    {
      id: 'AUD-ASSURE-002',
      timestamp: '2026-10-06T11:00:00Z',
      user: 'Michael Grant',
      action: 'Assurance pack generated',
      recordType: 'Assurance Pack',
      recordId: 'PACK-CHG-001-001',
      relatedIds: ['CHG-001'],
    },
    {
      id: 'AUD-ASSURE-003',
      timestamp: '2026-10-07T09:30:00Z',
      user: 'Sarah Jones',
      action: 'Board Pack generated',
      recordType: 'Board Pack',
      recordId: 'BP-2026-Q4-DRAFT',
      relatedIds: ['PERIOD-2026-Q4'],
    }
  );
}
